<template>
    <div id="app">
        <router-view/>
    </div>
</template>

<script>
    import { mapGetters } from 'vuex'
    export default {
        name: 'App',
        computed: {
            ...mapGetters([
                'githubUsername',
                'htmlTitle'
            ])
        },
        created() {
            this.$store.dispatch('Init')
            this.$store.dispatch('GetInfo')
            this.$setTitle(this.$route.meta.title)
            this.routeToViewport(this.$route)
            window.addEventListener('resize', this.onViewportResize)
            window.addEventListener('orientationchange', this.onViewportResize)
        },
        beforeDestroy() {
            window.removeEventListener('resize', this.onViewportResize)
            window.removeEventListener('orientationchange', this.onViewportResize)
        },
        methods: {
            routeToViewport(route) {
                const size = this.$util.getWindowSize()
                const mobile = size.height > size.width * 1.2
                const path = route.path || ''
                // 写作/编辑器只实现于桌面布局，窄屏也保留桌面路径。
                const desktopOnly = /^\/user\/blog\/(add|edit)/.test(path)
                if (mobile && path.indexOf('/mobile/') !== 0 && !desktopOnly) {
                    const mapped = path
                        .replace(/^\/user\/blog\/details\//, '/mobile/user/blog/details/')
                        .replace(/^\/user\/blog\/main/, '/mobile/user/blog/main')
                        .replace(/^\/user\/new\/main/, '/mobile/user/blog/main')
                        .replace(/^\/user\/project\/details\//, '/mobile/user/project/details/')
                        .replace(/^\/user\/project\/main/, '/mobile/user/project/main')
                        .replace(/^\/user\/self\/main/, '/mobile/user/self/main')
                    this.$router.replace(mapped.indexOf('/mobile/') === 0 ? mapped : '/mobile/user/blog/main')
                } else if (!mobile && path.indexOf('/mobile/') === 0) {
                    const mapped = path
                        .replace(/^\/mobile\/user\/blog\/details\//, '/user/blog/details/')
                        .replace(/^\/mobile\/user\/blog\/main/, '/user/blog/main')
                        .replace(/^\/mobile\/user\/project\/details\//, '/user/project/details/')
                        .replace(/^\/mobile\/user\/project\/main/, '/user/project/main')
                        .replace(/^\/mobile\/user\/self\/main/, '/user/self/main')
                    this.$router.replace(mapped.indexOf('/user/') === 0 ? mapped : '/user/blog/main')
                }
            },
            onViewportResize() {
                if (this.viewportTimer) clearTimeout(this.viewportTimer)
                this.viewportTimer = setTimeout(() => this.routeToViewport(this.$route), 150)
            }
        }
    }
</script>


