<template>
    <div style="min-height: 600px">
        <el-row :gutter="20">
            <el-col :span="16" class="main-content">
                <div class="list-toolbar">
                    <el-input
                        placeholder="搜索标题 / 摘要 / 标签"
                        v-model="searchInput"
                        @input="onSearchInput"
                        @clear="clearSearch"
                        clearable
                        class="search-box">
                        <i slot="prefix" class="el-icon-search"></i>
                    </el-input>
                    <el-button
                        v-if="filterCategory || activeTags.length || searchKey"
                        type="text"
                        @click="resetFilter">清除筛选</el-button>
                    <el-button type="text" icon="el-icon-share" @click="$share()">分享</el-button>
                    <el-button type="primary" icon="el-icon-edit" round plain
                        style="margin-left:8px" @click="goAdd">写博文</el-button>
                </div>

                <div v-if="query.loading && blogs.length === 0" class="empty-state">
                    <i class="el-icon-loading"></i>
                    <p class="empty-title">正在载入文章</p>
                </div>
                <div v-else-if="!query.loading && blogs.length === 0" class="empty-state">
                    <i :class="loadError ? 'el-icon-warning-outline' : 'el-icon-notebook-2'"></i>
                    <p class="empty-title">{{loadError ? '文章暂时无法载入' : '这里还没有文章'}}</p>
                    <p class="empty-sub">{{loadError ? '检查网络连接后重试。' : '在「发表博客」里填好分类与标签,文章会出现在这里。'}}</p>
                    <el-button v-if="loadError" type="primary" @click="retry">重试</el-button>
                    <el-button v-else type="primary" @click="goAdd">写一篇</el-button>
                </div>

                <div v-else-if="filteredBlogs.length === 0" class="empty-state">
                    <i class="el-icon-search"></i>
                    <p class="empty-title">没有匹配的文章</p>
                    <p class="empty-sub">当前筛选条件下没有命中。试着调整关键词,或清除筛选看看全部文章。</p>
                    <el-button type="text" @click="resetFilter">清除筛选</el-button>
                </div>

                <el-row :gutter="20" v-else>
                    <el-col :span="24" v-for="(item,index) in filteredBlogs" :key="index" style="margin-bottom: 14px">
                        <el-card shadow="never" class="blog-card">
                            <div class="blog-card-body" @click="goDetails(item)">
                                <div class="blog-cover-col" v-if="item.cover">
                                    <img :src="item.cover" class="blog-cover" alt="cover"/>
                                </div>
                                <div class="blog-main">
                                    <div class="blog-head">
                                        <span class="blog-title" @click.stop="goDetails(item)">{{item.title}}</span>
                                        <el-tag v-if="item.category" size="mini" type="success" class="blog-cat"
                                            @click.stop="setCategory(item.category)">{{item.category}}</el-tag>
                                        <span class="blog-ops" v-if="token">
                                            <el-button type="text" icon="el-icon-edit" @click.stop="editBlog(item)"></el-button>
                                            <el-button type="text" icon="el-icon-delete" @click.stop="deleteBlog(item)"></el-button>
                                        </span>
                                    </div>
                                    <p class="blog-summary" v-if="item.summary">{{item.summary}}</p>
                                    <div class="blog-foot">
                                        <span><i class="el-icon-date"></i> {{item.updateTime}}</span>
                                        <span class="blog-tags" v-if="item.tags && item.tags.length">
                                            <i class="el-icon-collection-tag"></i>
                                            <em v-for="t in item.tags" :key="t" @click.stop="toggleTag(t)">{{t}}</em>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </el-card>
                    </el-col>
                </el-row>

                <div style="text-align: center;margin-top: 10px" v-if="blogs.length > 0 && hasMore">
                    <el-button @click="loadMore" type="text" :loading="query.loading">{{query.loading ? '加载中…' : (loadError ? '重试加载' : '继续加载')}}</el-button>
                </div>
            </el-col>

            <el-col :span="8" class="side-content">
                <el-card shadow="never" class="filter-card" v-if="categories.length">
                    <div slot="header" class="filter-head"><i class="el-icon-folder-opened"></i> 分类</div>
                    <div class="chip-wrap">
                        <span class="vblog-tag" :class="{active: !filterCategory}" @click="setCategory('')">全部</span>
                        <span v-for="c in categories" :key="c.name"
                            class="vblog-tag" :class="{active: filterCategory === c.name}"
                            @click="setCategory(c.name)">{{c.name}} <i>({{c.count}})</i></span>
                    </div>
                </el-card>

                <el-card shadow="never" class="filter-card" v-if="tagList.length">
                    <div slot="header" class="filter-head"><i class="el-icon-collection-tag"></i> 标签</div>
                    <div class="chip-wrap">
                        <span v-for="t in tagList" :key="t.name"
                            class="vblog-tag" :class="{active: activeTags.indexOf(t.name) >= 0}"
                            @click="toggleTag(t.name)">{{t.name}} <i>({{t.count}})</i></span>
                    </div>
                </el-card>
            </el-col>
        </el-row>
    </div>
</template>

<script>
    import GistApi from '@/api/gist'
    import { mapGetters } from 'vuex'

    export default {
        name: 'BlogMain',
        data() {
            return {
                query: {
                    page: 1,
                    pageSize: 100,
                    loading: false
                },
                blogs: [],
                searchInput: '',
                searchKey: '',
                filterCategory: '',
                activeTags: [],
                debounceTimer: null,
                hasMore: true,
                loadError: false
            }
        },
        computed: {
            ...mapGetters([
                'githubUsername',
                'token'
            ]),
            categories() {
                const map = {}
                this.blogs.forEach((b) => {
                    if (b.category) map[b.category] = (map[b.category] || 0) + 1
                })
                return Object.keys(map).map((name) => ({ name, count: map[name] }))
            },
            tagList() {
                const map = {}
                this.blogs.forEach((b) => {
                    (b.tags || []).forEach((t) => {
                        map[t] = (map[t] || 0) + 1
                    })
                })
                return Object.keys(map).map((name) => ({ name, count: map[name] }))
            },
            filteredBlogs() {
                const key = this.searchKey.trim().toLowerCase()
                return this.blogs.filter((b) => {
                    if (this.filterCategory && b.category !== this.filterCategory) return false
                    if (this.activeTags.length) {
                        const bt = b.tags || []
                        if (!this.activeTags.every((t) => bt.indexOf(t) >= 0)) return false
                    }
                    if (key) {
                        const hay = (b.title + ' ' + (b.summary || '') + ' ' + (b.tags || []).join(' ')).toLowerCase()
                        if (hay.indexOf(key) < 0) return false
                    }
                    return true
                })
            }
        },
        watch: {
            '$route.query.tag'(newTag) {
                this.activeTags = newTag ? [newTag] : []
            }
        },
        mounted() {
            const presetTag = this.$route.query.tag
            if (presetTag) this.activeTags = [presetTag]
            this.list()
        },
        beforeDestroy() {
            clearTimeout(this.debounceTimer)
        },
        methods: {
            list() {
                if (this.query.loading) return
                this.query.loading = true
                this.loadError = false
                GistApi.list(this.query).then((response) => {
                    let result = response.data
                    if (result && result.length > 0) {
                        for (let i = 0; i < result.length; i++) {
                            if (!this.blogs.some((b) => b.id === result[i].id)) this.blogs.push(result[i])
                        }
                    }
                    this.hasMore = !!result && result.length === this.query.pageSize
                }).catch(() => {
                    this.loadError = true
                    this.$message({ message: '文章列表加载失败,请稍后重试', type: 'error' })
                }).then(() => {
                    this.query.loading = false
                })
            },
            retry() {
                this.list()
            },
            loadMore() {
                if (!this.hasMore || this.query.loading) return
                if (!this.loadError) this.query.page++
                this.list()
            },
            onSearchInput(val) {
                const self = this
                clearTimeout(this.debounceTimer)
                this.debounceTimer = setTimeout(() => {
                    self.searchKey = val || ''
                }, 300)
            },
            clearSearch() {
                this.searchInput = ''
                this.searchKey = ''
            },
            setCategory(name) {
                this.filterCategory = name
            },
            toggleTag(name) {
                const i = this.activeTags.indexOf(name)
                if (i >= 0) this.activeTags.splice(i, 1)
                else this.activeTags.push(name)
            },
            resetFilter() {
                this.filterCategory = ''
                this.activeTags = []
                this.clearSearch()
            },
            goDetails(item) {
                this.$router.push('/user/blog/details/' + item.id)
            },
            goAdd() {
                if (!this.token) {
                    this.$message({
                        message: '请绑定有效的Token',
                        type: 'warning'
                    })
                    return
                }
                this.$router.push('/user/blog/add')
            },
            editBlog(item) {
                if (!this.token) {
                    this.$message({
                        message: '请绑定有效的Token',
                        type: 'warning'
                    })
                    return
                }
                this.$router.push('/user/blog/edit/' + item.id)
            },
            deleteBlog(item) {
                if (!this.token) {
                    this.$message({ message: '请先绑定 Token', type: 'warning' })
                    return
                }
                this.$confirm('是否永久删除该博客?', '提示', {
                    confirmButtonText: '确定',
                    cancelButtonText: '取消',
                    type: 'warning'
                }).then(() => {
                    return GistApi.delete(item.id).then(() => {
                        this.$message({ message: '删除成功', type: 'success' })
                        const i = this.blogs.indexOf(item)
                        if (i >= 0) this.blogs.splice(i, 1)
                    })
                }).catch(() => {})
            }
        }
    }
</script>

<style>
    .list-toolbar {
        display: flex;
        align-items: center;
        margin-bottom: 16px;
    }
    .list-toolbar .search-box {
        flex: 1;
        max-width: 420px;
    }
    .blog-card-body {
        display: flex;
        cursor: pointer;
    }
    .blog-cover-col {
        flex: 0 0 160px;
        margin-right: 16px;
    }
    .blog-cover {
        width: 160px;
        height: 110px;
        object-fit: cover;
        border-radius: 10px;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    }
    .blog-main {
        flex: 1;
        min-width: 0;
    }
    .blog-head {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 6px;
    }
    .blog-title {
        font-size: 1.05rem;
        font-weight: 600;
        color: #303133;
        cursor: pointer;
    }
    .blog-title:hover {
        color: #42b983;
    }
    .blog-ops {
        margin-left: auto;
        flex: 0 0 auto;
    }
    .blog-ops .el-button {
        padding: 0 4px;
    }
    .blog-summary {
        color: #606266;
        font-size: 0.88rem;
        line-height: 1.6;
        margin: 0 0 8px;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        overflow: hidden;
    }
    .blog-foot {
        font-size: 0.78rem;
        color: #909399;
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: 14px;
    }
    .blog-foot .blog-tags em {
        font-style: normal;
        color: #409eff;
        cursor: pointer;
        margin-left: 4px;
    }
    .blog-foot .blog-tags em:hover {
        text-decoration: underline;
    }
    .filter-card {
        margin-bottom: 16px;
    }
    .filter-head {
        font-weight: 600;
        color: #303133;
    }
    .filter-head i {
        color: #42b983;
        margin-right: 4px;
    }
    .chip-wrap .vblog-tag i {
        font-style: normal;
        opacity: 0.7;
    }
    .chip-wrap .vblog-tag.active {
        background: #42b983;
        color: #fff;
    }
    .empty-state {
        text-align: center;
        padding: 60px 20px;
        color: #909399;
    }
    .empty-state i {
        font-size: 56px;
        color: #dcdfe6;
    }
    .empty-title {
        font-size: 1.1rem;
        color: #606266;
        margin: 14px 0 6px;
    }
    .empty-sub {
        font-size: 0.86rem;
        line-height: 1.7;
        max-width: 460px;
        margin: 0 auto 18px;
    }
</style>



