/**
 * CMS 元数据解析（零额外请求）
 *
 * GitHub Gist 的 list 接口只返回 description 与文件列表, 不返回正文。
 * 因此把文章的结构化元数据(category / tags / cover)编码进 gist 的
 * description 字段, 用不可见分隔符 ◈ 隔开:
 *
 *   <摘要>◈category=<分类>◈tags=<标签1>,<标签2>◈cover=<封面URL>
 *
 * 旧文章(description 不含 ◈)自动降级为「无分类纯摘要」, 完全向后兼容。
 * 正文永远保持纯 Markdown, 不含任何 frontmatter。
 */
const SEP = '◈'
const META_V2 = SEP + '@vblog:v2:'

function cleanString(value) {
  return typeof value === 'string' ? value.trim() : ''
}

export function parseDescription(raw) {
  const out = { summary: '', category: '', tags: [], cover: '' }
  if (!raw) return out

  // V2 JSON payload preserves separators, commas, and Unicode in all fields.
  const v2Index = raw.lastIndexOf(META_V2)
  if (v2Index >= 0) {
    out.summary = raw.slice(0, v2Index).trim()
    try {
      const meta = JSON.parse(decodeURIComponent(raw.slice(v2Index + META_V2.length)))
      out.category = cleanString(meta.category)
      out.tags = Array.isArray(meta.tags) ? meta.tags.map(cleanString).filter(Boolean) : []
      out.cover = cleanString(meta.cover)
      return out
    } catch (e) {
      // Malformed V2 data stays visible as a legacy summary instead of disappearing.
      out.summary = raw.trim()
      return out
    }
  }

  // Backward compatibility with the original delimiter format.
  if (raw.indexOf(SEP) < 0) {
    out.summary = raw.trim()
    return out
  }
  const parts = raw.split(SEP)
  out.summary = (parts[0] || '').trim()
  for (let i = 1; i < parts.length; i++) {
    const seg = parts[i].trim()
    if (seg.indexOf('category=') === 0) out.category = seg.slice(9).trim()
    else if (seg.indexOf('tags=') === 0) out.tags = seg.slice(5).split(',').map((t) => t.trim()).filter(Boolean)
    else if (seg.indexOf('cover=') === 0) out.cover = seg.slice(6).trim()
  }
  return out
}

export function encodeDescription(form) {
  const summary = cleanString(form.summary || form.description)
  const meta = {
    category: cleanString(form.category),
    tags: Array.isArray(form.tags) ? form.tags.map(cleanString).filter(Boolean) : [],
    cover: cleanString(form.cover)
  }
  if (!meta.category && !meta.tags.length && !meta.cover && summary.indexOf(SEP) < 0) return summary
  return summary + META_V2 + encodeURIComponent(JSON.stringify(meta))
}

// 估算阅读时长（中文 ~350 字/分钟，英文 ~200 词/分钟）
export function readingTime(content) {
  if (!content) return 1
  const cjk = (content.match(/[一-龥]/g) || []).length
  const words = (content.replace(/[一-龥]/g, ' ').match(/\b\w+\b/g) || []).length
  const minutes = cjk / 350 + words / 200
  return Math.max(1, Math.round(minutes))
}

// 从正文提取 h2/h3 生成目录（供详情页渲染，替代 extras.js 的 DOM 注入）
export function buildTOC(content) {
  const lines = (content || '').split('\n')
  const toc = []
  let inFence = false
  let i = 0
  for (const line of lines) {
    if (/^```/.test(line.trim())) {
      inFence = !inFence
      continue
    }
    if (inFence) continue
    const m = /^(#{2,3})\s+(.*)$/.exec(line)
    if (m) {
      const text = m[2].replace(/[#*`]/g, '').trim()
      const id = 'h-' + i + '-' + text.replace(/[^\w一-龥]+/g, '-').slice(0, 24)
      toc.push({ level: m[1].length, text, id, index: i })
      i++
    }
  }
  return toc
}

export function slugify(text, i) {
  return 'h-' + i + '-' + (text || '').replace(/[^\w一-龥]+/g, '-').slice(0, 24)
}



