// 令牌保险箱：与桌面 jiqiansi.github.io-令牌保险箱.html 同一套算法
// 格式: v1:<base64(salt16 | iv12 | tag16 | ciphertext)>
// 派生: PBKDF2-SHA256, salt=16B, 100000 轮 -> AES-GCM-256
// 仅用于本地可逆封装，绝不上传明文令牌。
const enc = new TextEncoder()
const dec = new TextDecoder()

// 内嵌密文（无密码不可还原）。换密码/换令牌时重新用桌面保险箱生成并替换此处。
export const VAULT_CIPHER = 'v1:lbxFxaDlWb7Sd3SkAD4NyBFyW8vFmGhLkit6u4clexhstgEJIp5QDwIjXVwJttulIuybtUbuXTQE026Naejh6oQspQUtzK5/c+P/1IZLXtRc6ZkY'

function b64(u8) {
  let s = ''
  for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i])
  return btoa(s)
}

function unb64(s) {
  return Uint8Array.from(atob(s), c => c.charCodeAt(0))
}

async function deriveKey(password, salt, mode) {
  const base = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveKey'])
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },
    base,
    { name: 'AES-GCM', length: 256 },
    false,
    [mode]
  )
}

export async function sealToken(token, password) {
  if (!/^ghp_|^github_pat_/.test(token)) throw new Error('令牌格式异常')
  if (password.length < 4) throw new Error('密码至少 4 位')
  const salt = crypto.getRandomValues(new Uint8Array(16))
  const iv = crypto.getRandomValues(new Uint8Array(12))
  const key = await deriveKey(password, salt, 'encrypt')
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(token)))
  const out = new Uint8Array(salt.length + iv.length + ct.length)
  out.set(salt, 0)
  out.set(iv, salt.length)
  out.set(ct, salt.length + iv.length)
  return 'v1:' + b64(out)
}

export async function openToken(cipher, password) {
  if (typeof cipher !== 'string' || !cipher.startsWith('v1:')) throw new Error('密文格式不对（应以 v1: 开头）')
  const raw = unb64(cipher.slice(3))
  if (raw.length < 44) throw new Error('密文长度异常')
  const salt = raw.slice(0, 16)
  const iv = raw.slice(16, 28)
  const ct = raw.slice(28)
  const key = await deriveKey(password, salt, 'decrypt')
  const pt = new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ct))
  const tok = dec.decode(pt)
  if (!/^ghp_|^github_pat_/.test(tok)) throw new Error('密码错误或密文损坏')
  return tok
}

export default { VAULT_CIPHER, sealToken, openToken }



