<template>
    <div :style="'background: #f8f8f8;min-height: '+windowSize.height+'px'">
        <van-nav-bar style="position:fixed;top:0;z-index: 9999; box-shadow: 0px -3px 10px #888888;width: 100%;" title="博客列表" right-text="分享"
            @click-right="$mobileShare()" />
        <div style="height: 60px;"></div>
        <div style="padding:8px 10px;background:#fff">
            <input v-model="searchInput" placeholder="搜索标题 / 摘要 / 标签" style="box-sizing:border-box;width:100%;height:36px;border:1px solid #dcdee0;border-radius:18px;padding:0 14px;font-size:0.86rem;outline:none" />
            <div v-if="categories.length" style="display:flex;overflow-x:auto;white-space:nowrap;padding-top:8px">
                <span @click.stop="setCategory('')" :style="filterChip(!activeCategory)">全部</span>
                <span v-for="c in categories" :key="c" @click.stop="setCategory(c)" :style="filterChip(activeCategory===c)">{{c}}</span>
            </div>
            <div v-if="tags.length" style="display:flex;overflow-x:auto;white-space:nowrap;padding-top:6px">
                <span v-for="t in tags" :key="t" @click.stop="toggleTag(t)" :style="filterChip(activeTags.indexOf(t)>=0,'#409eff')">{{t}}</span>
            </div>
        </div>
        <div v-for="(item,index) in visibleBlogs" :key="'p'+index" @click="goDetails(item.id)" style="cursor:pointer">
            <van-panel style="margin-bottom: 10px" :title="item.title" :desc="'更新时间 '+item.updateTime">
                <img v-if="item.cover" :src="item.cover" style="width:100%;display:block" alt="cover"/>
                <div style="padding: 7px 15px 0 15px">
                    <span v-if="item.category" style="display:inline-block;font-size:0.72rem;color:#67c23a;background:#f0f9eb;border-radius:999px;padding:1px 8px;margin-right:6px">📁 {{item.category}}</span>
                    <span v-for="t in (item.tags||[])" :key="t" style="display:inline-block;font-size:0.72rem;color:#409eff;background:#ecf5ff;border-radius:999px;padding:1px 8px;margin-right:6px">{{t}}</span>
                </div>
                <div style="padding: 7px 15px 7px 15px;color: #303133;font-size: 0.9rem">{{$util.cutStr(item.summary || item.description,50)}}</div>
                <div v-if="token" style="padding: 0 15px 8px;text-align:right">
                    <button @click.stop="editBlog(item.id)" style="border:0;background:transparent;color:#1989fa;font-size:0.8rem">编辑</button>
                    <button @click.stop="deleteBlog(item)" style="border:0;background:transparent;color:#ee0a24;font-size:0.8rem;margin-left:12px">删除</button>
                </div>
            </van-panel>
        </div>
        <div v-if="loading && blogs.length===0" style="text-align:center;padding:50px 20px;color:#969799">正在载入文章…</div>
        <div v-if="!loading && loadError && blogs.length===0" style="text-align:center;padding:50px 20px;color:#969799">
            <div>文章暂时无法载入</div><button @click="list" style="margin-top:10px;border:0;background:transparent;color:#1989fa">重试</button>
        </div>
        <div v-if="!loading && !loadError && blogs.length>0 && visibleBlogs.length===0" style="text-align:center;padding:50px 20px;color:#969799">
            <div style="font-size:40px">🔎</div>
            <div style="margin-top:12px;font-size:1rem;color:#646566">没有匹配的文章</div>
            <div style="margin-top:8px;font-size:0.84rem">换个关键词试试。</div>
        </div>
        <div v-if="!loading && !loadError && blogs.length===0" style="text-align:center;padding:60px 20px;color:#969799">
            <div style="font-size:44px">📝</div>
            <div style="margin-top:12px;font-size:1rem;color:#646566">这里还没有文章</div>
            <div style="margin-top:8px;font-size:0.84rem;line-height:1.7">在电脑端「发表博客」里填好分类与标签,文章会出现在这里。</div>
        </div>
        <div v-if="blogs.length && hasMore" style="text-align:center;padding:8px 0 18px">
            <button @click="loadMore" :disabled="loading" style="border:0;background:transparent;color:#1989fa;font-size:0.9rem">{{loading ? '加载中…' : (loadError ? '重试加载' : '加载更多')}}</button>
        </div>
        <div style="height: 100px;"></div>

    </div>
</template>

<script>
    import { mapGetters } from 'vuex'
    import GistApi from '@/api/gist'
    export default {
        data() {
            return {
                windowSize: this.$util.getWindowSize(),
                query: {
                    page: 1,
                    pageSize: 20,
                    pageNumber: 1
                },
                searchInput: "",
                activeCategory: '',
                activeTags: [],
                loading: false,
                loadError: false,
                hasMore: true,
                blogs: []
            }
        },
        computed: {
            ...mapGetters(['token']),
            categories() {
                const out = []
                this.blogs.forEach((b) => {
                    if (b.category && out.indexOf(b.category) < 0) out.push(b.category)
                })
                return out
            },
            tags() {
                const out = []
                this.blogs.forEach((b) => {
                    const rowTags = b.tags || []
                    rowTags.forEach((tag) => {
                        if (tag && out.indexOf(tag) < 0) out.push(tag)
                    })
                })
                return out
            },
            visibleBlogs() {
                const key = (this.searchInput || '').trim().toLowerCase()
                return this.blogs.filter((b) => {
                    if (this.activeCategory && b.category !== this.activeCategory) return false
                    if (this.activeTags.length && !this.activeTags.every((t) => (b.tags || []).indexOf(t) >= 0)) return false
                    const hay = ((b.title || '') + ' ' + (b.summary || '') + ' ' + (b.tags || []).join(' ')).toLowerCase()
                    return !key || hay.indexOf(key) >= 0
                })
            }
        },
        mounted() {
            this.list()
        },
        methods: {
            filterChip(active, color) {
                const base = color || '#67c23a'
                return 'display:inline-block;margin-right:6px;padding:3px 10px;border-radius:999px;font-size:0.75rem;background:' + (active ? base : '#f2f3f5') + ';color:' + (active ? '#fff' : '#646566')
            },
            setCategory(name) {
                this.activeCategory = name
            },
            toggleTag(name) {
                const i = this.activeTags.indexOf(name)
                if (i >= 0) this.activeTags.splice(i, 1)
                else this.activeTags.push(name)
            },
            resetFilter() {
                this.searchInput = ''
                this.activeCategory = ''
                this.activeTags = []
            },
            goDetails(id) {
                this.$router.push('/mobile/user/blog/details/' + id)
            },
            editBlog(id) {
                // 编辑器只实现于桌面布局
                this.$router.push('/user/blog/edit/' + id)
            },
            deleteBlog(item) {
                this.$dialog.confirm({
                    title: '删除文章',
                    message: '将永久删除《' + item.title + '》,无法恢复。',
                    confirmButtonText: '删除',
                    cancelButtonText: '取消'
                }).then(() => {
                    return GistApi.delete(item.id).then(() => {
                        this.$toast.success('已删除')
                        const i = this.blogs.indexOf(item)
                        if (i >= 0) this.blogs.splice(i, 1)
                    })
                }).catch(() => {})
            },
            list() {
                if (this.loading) return
                this.loading = true
                this.loadError = false
                this.$toast.loading({
                    duration: 0,
                    forbidClick: true,
                    message: '加载中'
                })
                GistApi.list(this.query).then((response) => {
                    let result = response.data
                    let pageNumber = this.$util.parseHeaders(response.headers)
                    if (pageNumber) {
                        this.query.pageNumber = pageNumber
                    }
                    if (result.length == 0) {
                        this.hasMore = false
                        this.loading = false
                        return
                    }
                    this.hasMore = result.length === this.query.pageSize
                    for (let i = 0; i < result.length; i++) {
                        for (let key in result[i].files) {
                            let data = {}
                            data['title'] = key
                            data['url'] = result[i].files[key]
                            data['description'] = result[i]['summary'] || result[i]['description']
                            data['summary'] = result[i]['summary'] || ''
                            data['category'] = result[i]['category'] || ''
                            data['tags'] = result[i]['tags'] || []
                            data['cover'] = result[i]['cover'] || ''
                            data['id'] = result[i]['id']
                            data['createTime'] = this.$util.utcToLocal(result[i]['created_at'])
                            data['updateTime'] = this.$util.utcToLocal(result[i]['updated_at'])
                            data['hide'] = false
                            if (!this.blogs.some((b) => b.id === data.id)) this.blogs.push(data)
                            break
                        }
                    }
                }).catch(() => {
                    this.loadError = true
                    if (this.query.page > 1) this.query.page--
                }).then(() => {
                    this.$toast.clear()
                    this.loading = false
                })
            },
            loadMore() {
                if (!this.hasMore || this.loading) return
                if (!this.loadError) this.query.page++
                this.list()
            }
        }
    }
</script>


