import Cookie from '@/utils/cookie'
import UserApi from '@/api/user'
import store from '../index'
import Vue from 'vue'

const TOKEN_KEY = 'TOKEN_KEY'

// 将旧版 Path=/ Cookie 一次性迁移到本地存储，避免令牌随 Pages 静态资源请求发送。
const TOKEN_LIFETIME = 30 * 24 * 60 * 60 * 1000

function parseStoredToken(value) {
    if (!value) return null
    try {
        const parsed = JSON.parse(value)
        if (parsed && typeof parsed.token === 'string') return parsed
    } catch (e) {}
    // Upgrade an older localStorage string value once, with a finite lifetime.
    return { token: value, expiresAt: Date.now() + TOKEN_LIFETIME, migrated: true }
}

function loadToken() {
    let legacyToken = null
    try {
        legacyToken = Cookie.getAttribute(TOKEN_KEY) || null
        const storedValue = window.localStorage.getItem(TOKEN_KEY)
        const stored = parseStoredToken(storedValue)
        if (stored && (!stored.expiresAt || stored.expiresAt > Date.now())) {
            if (stored.migrated || !stored.expiresAt) {
                window.localStorage.setItem(TOKEN_KEY, JSON.stringify({ token: stored.token, expiresAt: Date.now() + TOKEN_LIFETIME }))
            }
            if (legacyToken) Cookie.remove(TOKEN_KEY)
            return stored.token
        }
        if (storedValue) window.localStorage.removeItem(TOKEN_KEY)
        if (legacyToken) {
            window.localStorage.setItem(TOKEN_KEY, JSON.stringify({ token: legacyToken, expiresAt: Date.now() + TOKEN_LIFETIME }))
            Cookie.remove(TOKEN_KEY)
            return legacyToken
        }
    } catch (e) {
        try { Cookie.remove(TOKEN_KEY) } catch (ignore) {}
    }
    return null
}

function saveToken(value) {
    window.localStorage.setItem(TOKEN_KEY, JSON.stringify({ token: value, expiresAt: Date.now() + TOKEN_LIFETIME }))
    Cookie.remove(TOKEN_KEY)
}

function removeToken() {
    window.localStorage.removeItem(TOKEN_KEY)
    Cookie.remove(TOKEN_KEY)
}

const token = {
    state: {
        token: loadToken()
    },

    mutations: {
        SET_TOKEN: (state, value) => {
            state.token = value
            saveToken(value)
        },
        REMOVE_TOKEN: (state) => {
            state.token = null
            removeToken()
        }
    },

    actions: {
        async Authentication({ commit }, accessToken) {
            try {
                const response = await UserApi.verifyToken(accessToken)
                const result = response.data
                const githubUsername = store.state.configuration.githubUsername
                if (githubUsername !== result.login) {
                    Vue.prototype.$message({
                        message: 'Token用户不一致',
                        type: 'error'
                    })
                    return false
                }
                commit('SET_TOKEN', accessToken)
                Vue.prototype.$notify({
                    title: '成功',
                    message: 'Token绑定成功',
                    type: 'success'
                })
                return true
            } catch (error) {
                return false
            }
        },
        Cancellation({ commit }) {
            commit('REMOVE_TOKEN')
            Vue.prototype.$message({
                message: 'Token取消绑定',
                type: 'info'
            })
        },
    }
}

export default token


