// Configure the shared mavon-editor markdown-it instance for untrusted public Gist content.
export function secureMarkdown(markdownIt) {
  markdownIt.set({ html: false })
  const rules = markdownIt.renderer.rules
  const defaultLinkOpen = rules.link_open || function (tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options)
  }
  rules.link_open = function (tokens, idx, options, env, self) {
    const token = tokens[idx]
    const targetIndex = token.attrIndex('target')
    if (targetIndex < 0) token.attrPush(['target', '_blank'])
    else token.attrs[targetIndex][1] = '_blank'

    const relIndex = token.attrIndex('rel')
    const rel = relIndex < 0 ? [] : token.attrs[relIndex][1].split(/\s+/)
    if (rel.indexOf('noopener') < 0) rel.push('noopener')
    if (rel.indexOf('noreferrer') < 0) rel.push('noreferrer')
    if (relIndex < 0) token.attrPush(['rel', rel.join(' ')])
    else token.attrs[relIndex][1] = rel.join(' ')

    return defaultLinkOpen(tokens, idx, options, env, self)
  }
  return markdownIt
}



