<template>
    <div style="min-height: 600px">
        <div v-if="loadError" class="detail-load-error">
            文章载入失败。<el-button type="text" @click="loadAll">重试</el-button>
        </div>
        <el-row :gutter="20" v-loading="loading" v-else>
            <el-col :span="17" class="main-content">
                <el-card shadow="never" style="margin-bottom: 20px">
                    <div class="detail-head">
                        <div class="detail-head-ops">
                            <el-button type="text" icon="el-icon-share" @click="$share()">分享</el-button>
                            <el-button type="text" icon="el-icon-edit" v-if="token" @click="edit">编辑</el-button>
                            <el-button type="text" icon="el-icon-more-outline" @click="more">更多博客</el-button>
                        </div>
                        <h1 class="detail-title">{{blog.title}}</h1>
                        <p v-if="blog.description" class="detail-summary">{{blog.description}}</p>
                        <div class="detail-meta">
                            <span v-if="blog.category" class="dm-cat">
                                <i class="el-icon-folder"></i> {{blog.category}}
                            </span>
                            <span><i class="el-icon-date"></i> 发布 {{blog.createTime}}</span>
                            <span><i class="el-icon-refresh"></i> 更新 {{blog.updateTime}}</span>
                            <span><i class="el-icon-reading"></i> 约 {{readingMinutes}} 分钟</span>
                        </div>
                        <div class="detail-tags" v-if="blog.tags && blog.tags.length">
                            <i class="el-icon-collection-tag"></i>
                            <em v-for="t in blog.tags" :key="t" @click="goTag(t)">{{t}}</em>
                        </div>
                    </div>

                    <img v-if="blog.cover" :src="blog.cover" class="vblog-cover" alt="cover"/>

                    <div v-html="blog.content" class="markdown-body detail-body"></div>

                    <div class="detail-foot">
                        <el-button type="text" :disabled="!prevBlog" @click="goBlog(prevBlog)">
                            <i class="el-icon-arrow-left"></i> {{prevBlog ? prevBlog.title : '上一篇'}}
                        </el-button>
                        <el-button type="text" :disabled="!nextBlog" @click="goBlog(nextBlog)">
                            {{nextBlog ? nextBlog.title : '下一篇'}} <i class="el-icon-arrow-right"></i>
                        </el-button>
                    </div>
                </el-card>

                <el-card shadow="never" class="rel-card" v-if="related.length">
                    <div slot="header" class="rel-head"><i class="el-icon-connection"></i> 相关文章</div>
                    <ul class="rel-list">
                        <li v-for="r in related" :key="r.id" @click="goBlog(r)">
                            <span class="rel-title">{{r.title}}</span>
                            <span class="rel-cat" v-if="r.category">{{r.category}}</span>
                        </li>
                    </ul>
                </el-card>
            </el-col>

            <el-col :span="7" class="side-content">
                <el-card shadow="never" class="toc-card" v-if="toc.length">
                    <div slot="header" class="toc-head"><i class="el-icon-menu"></i> 目录</div>
                    <ul class="toc-list">
                        <li v-for="h in toc" :key="h.id" :class="'lv'+h.level">
                            <a :href="'#'+h.id" @click.prevent="scrollTo(h.id)">{{h.text}}</a>
                        </li>
                    </ul>
                </el-card>
            </el-col>
        </el-row>
    </div>
</template>

<script>
    import GistApi from '@/api/gist'
    import { mapGetters } from 'vuex'
    import { readingTime, buildTOC } from '@/utils/cms'

    export default {
        name: 'BlogDetails',
        data() {
            return {
                loading: true,
                loadError: false,
                blog: {
                    id: "", title: "", content: "", description: "",
                    category: "", tags: [], cover: "",
                    createTime: "", updateTime: ""
                },
                toc: [],
                readingMinutes: 1,
                allBlogs: [],
                indexLoaded: false,
                prevBlog: null,
                nextBlog: null,
                related: []
            }
        },
        computed: {
            ...mapGetters([
                'githubUsername',
                'token'
            ])
        },
        watch: {
            '$route.params.id'(newId) {
                if (newId && newId !== this.blog.id) {
                    window.scrollTo(0, 0)
                    this.blog.id = newId
                    this.loadAll()
                }
            }
        },
        mounted() {
            this.blog.id = this.$route.params.id
            this.loadAll()
        },
        methods: {
            loadAll() {
                const requestedId = this.blog.id
                this.loading = true
                this.loadError = false
                GistApi.single(requestedId).then((response) => {
                    if (requestedId !== this.blog.id) return
                    let result = response.data
                    for (let key in result.files) {
                        this.blog['title'] = key
                        this.blog['description'] = result['summary'] || ''
                        this.blog['category'] = result['category']
                        this.blog['tags'] = result['tags'] || []
                        this.blog['cover'] = result['cover']
                        this.blog['createTime'] = this.$util.utcToLocal(result['created_at'])
                        this.blog['updateTime'] = this.$util.utcToLocal(result['updated_at'])
                        // 截断的大文件走 raw_url 取全文，避免只渲染前 1MiB
                        return GistApi.fileContent(result.files[key]).then((raw) => {
                            if (requestedId !== this.blog.id) return
                            this.blog['content'] = this.$markdown(raw)
                            this.readingMinutes = readingTime(raw)
                            this.toc = buildTOC(raw)
                            this.computeNav()
                            this.$nextTick(() => this.$nextTick(() => this.applyHeadingIds()))
                        })
                    }
                }).catch(() => {
                    if (requestedId === this.blog.id) this.loadError = true
                }).then(() => {
                    if (requestedId === this.blog.id) this.loading = false
                })
                // 首次拉取完整列表建立导航索引,同一详情组件内切换文章时复用索引
                if (!this.indexLoaded) {
                    GistApi.listAll(100).then((rows) => {
                        if (requestedId !== this.blog.id) return
                        this.allBlogs = rows || []
                        this.indexLoaded = true
                        this.computeNav()
                    }).catch(() => {
                        if (requestedId !== this.blog.id) return
                        this.allBlogs = []
                        this.prevBlog = null
                        this.nextBlog = null
                        this.related = []
                    })
                } else {
                    this.computeNav()
                }
            },
            // 依据与目录相同的正文标题顺序，给真实 heading 节点设置锚点。
            applyHeadingIds() {
                const headings = this.$el.querySelectorAll('.detail-body h2, .detail-body h3')
                this.toc.forEach((item, index) => {
                    if (headings[index]) headings[index].id = item.id
                })
            },
            computeNav() {
                const list = this.allBlogs
                const idx = list.findIndex((b) => b.id === this.blog.id)
                this.prevBlog = idx > 0 ? list[idx - 1] : null
                this.nextBlog = idx >= 0 && idx < list.length - 1 ? list[idx + 1] : null
                // 相关:同分类或共享标签,排除自己
                const me = this.blog
                this.related = list.filter((b) => {
                    if (b.id === me.id) return false
                    if (me.category && b.category === me.category) return true
                    if (me.tags && me.tags.length) {
                        const bt = b.tags || []
                        if (me.tags.some((t) => bt.indexOf(t) >= 0)) return true
                    }
                    return false
                }).slice(0, 5)
            },
            scrollTo(id) {
                const el = document.getElementById(id)
                if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' })
            },
            goBlog(b) {
                if (b) this.$router.push('/user/blog/details/' + b.id)
            },
            goTag(t) {
                this.$router.push({ path: '/user/blog/main', query: { tag: t } })
            },
            edit() {
                if (!this.token) {
                    this.$message({
                        message: '请绑定有效的Token',
                        type: 'warning'
                    })
                    return
                }
                this.$router.push('/user/blog/edit/' + this.blog.id)
            },
            more() {
                this.$router.push('/user/blog/main')
            }
        }
    }
</script>

<style>
    .detail-head {
        border-bottom: 1px solid #ebeef5;
        padding-bottom: 14px;
        margin-bottom: 16px;
    }
    .detail-head-ops {
        float: right;
        white-space: nowrap;
    }
    .detail-head-ops .el-button {
        padding: 0 4px;
    }
    .detail-title {
        font-size: 1.6rem;
        color: #303133;
        margin: 0 0 10px;
        word-break: break-word;
    }
    .detail-summary {
        margin: 0 0 10px;
        color: #606266;
        line-height: 1.65;
    }
    .detail-meta {
        font-size: 0.82rem;
        color: #909399;
        display: flex;
        flex-wrap: wrap;
        gap: 16px;
    }
    .detail-meta .dm-cat {
        color: #67c23a;
        font-weight: 600;
    }
    .detail-tags {
        margin-top: 10px;
        font-size: 0.8rem;
        color: #909399;
    }
    .detail-tags em {
        font-style: normal;
        color: #409eff;
        cursor: pointer;
        margin-left: 6px;
        padding: 1px 8px;
        background: #ecf5ff;
        border-radius: 999px;
    }
    .detail-tags em:hover {
        background: #409eff;
        color: #fff;
    }
    .detail-body {
        min-height: 120px;
    }
    .detail-foot {
        display: flex;
        justify-content: space-between;
        margin-top: 24px;
        padding-top: 14px;
        border-top: 1px dashed #ebeef5;
    }
    .rel-card .rel-head, .toc-head {
        font-weight: 600;
        color: #303133;
    }
    .rel-card .rel-head i, .toc-head i {
        color: #42b983;
        margin-right: 4px;
    }
    .rel-list {
        list-style: none;
        margin: 0;
        padding: 0;
    }
    .rel-list li {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 8px 0;
        border-bottom: 1px dashed #f0f0f0;
        cursor: pointer;
    }
    .rel-list li:hover .rel-title {
        color: #42b983;
    }
    .rel-cat {
        font-size: 0.75rem;
        color: #67c23a;
    }
    .toc-list {
        list-style: none;
        margin: 0;
        padding: 0;
        font-size: 0.86rem;
    }
    .toc-list li {
        line-height: 2;
    }
    .toc-list li.lv3 {
        padding-left: 16px;
    }
    .toc-list a {
        color: #606266;
        text-decoration: none;
        display: block;
    }
    .toc-list a:hover {
        color: #42b983;
    }
</style>



