import axios from 'axios'
import request from '@/utils/request'
import store from '../store/index'
import { parseDescription, encodeDescription } from '@/utils/cms'
import util from '@/utils/util'

function normalizeGist(gist) {
    const meta = parseDescription(gist.description)
    const firstFile = Object.keys(gist.files || {})[0] || ''
    return Object.assign({}, gist, {
        title: firstFile,
        summary: meta.summary,
        category: meta.category,
        tags: meta.tags,
        cover: meta.cover,
        updateTime: gist.updated_at ? util.utcToLocal(gist.updated_at) : ''
    })
}

export default {
    normalizeGist,
    list: function (query) {
        let githubUsername = store.state.configuration.githubUsername
        return request({
            url: `/users/${githubUsername}/gists?page=${query.page}&per_page=${query.pageSize}`
        }).then((response) => {
            if (Array.isArray(response.data)) response.data = response.data.map(normalizeGist)
            return response
        })
    },
    single: function (id) {
        return request({
            url: '/gists/' + id
        }).then((response) => {
            response.data = normalizeGist(response.data)
            return response
        })
    },
    rawFile: function (url) {
        // raw_url is a public CDN URL; use a separate unauthenticated client so the PAT
        // held by the GitHub API request interceptor is never sent to another host.
        return axios.get(url, {
            timeout: 20000,
            responseType: 'text',
            headers: { Accept: 'text/plain' },
            transformResponse: [(data) => data]
        })
    },
    fileContent: function (file) {
        if (!file || typeof file.content !== 'string') {
            return Promise.reject(new Error('Gist 文件内容不存在'))
        }
        if (!file.truncated) return Promise.resolve(file.content)
        if (!file.raw_url) return Promise.reject(new Error('Gist 文件被截断且没有 raw_url，已阻止不完整编辑'))
        return this.rawFile(file.raw_url).then((response) => {
            if (typeof response.data !== 'string') throw new Error('无法取得完整 Gist 正文')
            return response.data
        })
    },
    // list 接口单页最多 100 条。详情页需要完整索引来计算上下篇和相关文章。
    listAll: function (pageSize, maxPages) {
        const size = Math.min(Math.max(parseInt(pageSize || 100, 10), 1), 100)
        const pageLimit = Math.min(Math.max(parseInt(maxPages || 3, 10), 1), 10)
        const all = []
        const fetchPage = (page) => this.list({ page, pageSize: size }).then((response) => {
            const rows = Array.isArray(response.data) ? response.data : []
            all.push.apply(all, rows)
            if (page >= pageLimit || !util.hasNextPage(response.headers)) return all
            return fetchPage(page + 1)
        })
        return fetchPage(1)
    },

    create: function (form) {
        let files = {}
        files[form.title] = { content: form.content }
        const description = encodeDescription(form)
        return request({
            url: '/gists',
            method: 'post',
            data: {
                "description": description,
                "public": true,
                "files": files
            }
        })
    },
    /**
     * 编辑 gist
     *
     * GitHub 语义: files 里出现的 key 是"最终状态"。
     * 只给新文件名 => 等于新增一个文件, 旧文件仍留在 gist 里,
     * 列表页取 files 的第一个 key 时就会显示旧标题。
     * 所以改名必须把旧文件名显式置为 null(删除)。
     */
    edit: function (form) {
        let files = {}
        let oldTitle = form.originalTitle || form.title
        if (oldTitle !== form.title) {
            files[oldTitle] = null
        }
        files[form.title] = { content: form.content }
        const description = encodeDescription(form)
        return request({
            url: '/gists/' + form.id,
            method: 'PATCH',
            data: {
                "description": description,
                "public": true,
                "files": files
            }
        })
    },
    delete: function (id) {
        return request({
            url: '/gists/' + id,
            method: 'DELETE',
        })
    },
}



