<template>
    <div>
        <van-tabbar :value="active" @change="onChange">
            <van-tabbar-item v-for="item in mobileItems" :key="item.path" :to="item.path" :icon="item.meta.icon">
                {{item.meta.title}}
            </van-tabbar-item>
        </van-tabbar>
    </div>
</template>

<script>
    import { mapGetters } from 'vuex'
    import { constantRouterMap } from '@/router'
    export default {
        data() {
            return {
                constantRouterMap
            }
        },
        computed: {
            ...mapGetters(['token', 'mini']),
            mobileItems() {
                return this.constantRouterMap.filter((item) => item.meta && item.meta.type === 'mobile' &&
                    (this.token || !item.meta.LoginRequired) && (!this.mini || !item.meta.mini))
            },
            active() {
                const path = this.$route.path || ''
                const index = this.mobileItems.findIndex((item) => path.indexOf(item.path + '/') === 0 || path === item.path)
                return index < 0 ? 0 : index
            }
        },
        methods: {
            onChange(index) {
                const item = this.mobileItems[index]
                if (item) this.$router.push(item.path)
            }
        }
    }
</script>


