<template>
    <div>
        <van-nav-bar style="position:fixed;top:0;z-index: 9999; box-shadow: 0px -5px 10px #888888;width: 100%;" :title="blog.title"
            left-text="返回" right-text="分享" @click-left="$router.go(-1)" @click-right="$mobileShare()" left-arrow/>
        <div style="height: 60px;"></div>
        <div v-if="loadError" style="text-align:center;padding:40px 20px;color:#969799">文章载入失败。<button @click="load" style="border:0;background:transparent;color:#1989fa">重试</button></div>
        <div v-if="!loadError" style="font-size: 0.9rem;line-height: 1.5;color: #606c71;padding: 10px 10px 0px 10px">
            发布 {{blog.createTime}}
            <br> 更新 {{blog.updateTime}}
            <span v-if="readingMinutes"> · 约 {{readingMinutes}} 分钟</span>
            <button v-if="token" @click="editBlog" style="float:right;border:0;background:transparent;color:#1989fa;font-size:0.86rem">✏️ 编辑</button>
        </div>
        <div v-if="!loadError" style="font-size: 1.0rem;line-height: 1.5;color: #303133;border-bottom: 1px solid #E4E7ED;padding: 0px 10px">
            <pre style="font-family: '微软雅黑';white-space:pre-wrap;word-break:break-word;margin:6px 0">{{blog.description}}</pre>
            <div style="font-size:0.8rem;color:#67c23a;padding-top:4px" v-if="blog.category">📁 {{blog.category}}</div>
            <div style="font-size:0.8rem;color:#409eff;padding-top:4px" v-if="blog.tags && blog.tags.length">
                <span v-for="t in blog.tags" :key="t" style="display:inline-block;background:#ecf5ff;border-radius:999px;padding:1px 8px;margin:2px 6px 2px 0">🏷 {{t}}</span>
            </div>
        </div>
        <img v-if="!loadError && blog.cover" :src="blog.cover" style="width:calc(100% - 20px);margin:10px;border-radius:10px" alt="cover"/>
        <div v-if="!loadError && toc.length" style="margin:10px;background:#fff;border-radius:10px;padding:10px 14px">
            <div style="font-weight:600;color:#303133;margin-bottom:6px">📑 目录</div>
            <div v-for="h in toc" :key="h.id" :style="'padding:4px 0;font-size:0.86rem;'+(h.level===3?'padding-left:16px':'')">
                <a :href="'#'+h.id" @click.prevent="scrollTo(h.id)" style="color:#409eff;text-decoration:none">{{h.text}}</a>
            </div>
        </div>
        <div v-if="!loadError" v-html="blog.content" class="markdown-body" style="padding: 10px"></div>
        <div v-if="!loadError && (prevBlog || nextBlog)" style="margin:10px;background:#fff;border-radius:10px;padding:10px 14px;display:flex;justify-content:space-between;gap:12px">
            <a v-if="prevBlog" @click="goBlog(prevBlog)" style="color:#1989fa;flex:1">‹ {{prevBlog.title}}</a>
            <span v-else style="flex:1"></span>
            <a v-if="nextBlog" @click="goBlog(nextBlog)" style="color:#1989fa;flex:1;text-align:right">{{nextBlog.title}} ›</a>
        </div>
        <div v-if="!loadError && related.length" style="margin:10px;background:#fff;border-radius:10px;padding:10px 14px">
            <div style="font-weight:600;color:#303133;margin-bottom:6px">相关文章</div>
            <div v-for="item in related" :key="item.id" @click="goBlog(item)" style="padding:7px 0;border-bottom:1px solid #f2f3f5;color:#1989fa">{{item.title}}</div>
        </div>
        <div style="height: 100px;"></div>
    </div>
</template>


<script>
    import { mapGetters } from 'vuex'
    import GistApi from '@/api/gist'
    import { readingTime, buildTOC } from '@/utils/cms'
    export default {
        data() {
            return {
                blog: {
                    id: "",
                    title: "",
                    content: "",
                    description: "",
                    category: "",
                    tags: [],
                    cover: "",
                    createTime: "",
                    updateTime: ""
                },
                toc: [],
                readingMinutes: 0,
                allBlogs: [],
                indexLoaded: false,
                prevBlog: null,
                nextBlog: null,
                related: [],
                loadError: false
            }

        },
        computed: {
            ...mapGetters(['token'])
        },
        watch: {
            '$route.params.id'(newId) {
                if (newId && newId !== this.blog.id) {
                    window.scrollTo(0, 0)
                    this.blog.id = newId
                    this.blog.title = ''
                    this.blog.content = ''
                    this.blog.description = ''
                    this.blog.category = ''
                    this.blog.tags = []
                    this.blog.cover = ''
                    this.toc = []
                    this.prevBlog = null
                    this.nextBlog = null
                    this.related = []
                    this.load()
                }
            }
        },
        mounted() {
            this.blog.id = this.$route.params.id
            this.load()
        },
        methods: {
            load() {
                const requestedId = this.blog.id
                this.loadError = false
                this.$toast.loading({
                    duration: 0,
                    forbidClick: true,
                    message: '加载中'
                })
                GistApi.single(requestedId).then((response) => {
                    if (requestedId !== this.blog.id) return
                    let result = response.data
                    for (let key in result.files) {
                        this.blog['title'] = key
                        this.blog['description'] = result['summary'] || ''
                        this.blog['category'] = result['category'] || ''
                        this.blog['tags'] = result['tags'] || []
                        this.blog['cover'] = result['cover'] || ''
                        this.blog['createTime'] = this.$util.utcToLocal(result['created_at'])
                        this.blog['updateTime'] = this.$util.utcToLocal(result['updated_at'])
                        // 截断的大文件走 raw_url 取全文，避免只渲染前 1MiB
                        return GistApi.fileContent(result.files[key]).then((raw) => {
                            if (requestedId !== this.blog.id) return
                            this.blog['content'] = this.$markdown(raw)
                            this.readingMinutes = readingTime(raw)
                            this.toc = buildTOC(raw)
                            this.computeNav()
                            this.$nextTick(() => this.$nextTick(() => this.applyHeadingIds()))
                        })
                    }
                }).catch(() => {
                    if (requestedId === this.blog.id) {
                        this.loadError = true
                        this.$toast.fail('文章加载失败,请稍后重试')
                    }
                }).then(() => {
                    if (requestedId === this.blog.id) this.$toast.clear()
                })
                if (!this.indexLoaded) {
                    GistApi.listAll(100).then((rows) => {
                        if (requestedId !== this.blog.id) return
                        this.allBlogs = rows || []
                        this.indexLoaded = true
                        this.computeNav()
                    }).catch(() => {
                        if (requestedId === this.blog.id) {
                            this.allBlogs = []
                            this.prevBlog = null
                            this.nextBlog = null
                            this.related = []
                        }
                    })
                } else {
                    this.computeNav()
                }
            },
            computeNav() {
                const list = this.allBlogs
                const idx = list.findIndex((item) => item.id === this.blog.id)
                this.prevBlog = idx > 0 ? list[idx - 1] : null
                this.nextBlog = idx >= 0 && idx < list.length - 1 ? list[idx + 1] : null
                this.related = list.filter((item) => {
                    if (item.id === this.blog.id) return false
                    if (this.blog.category && item.category === this.blog.category) return true
                    const tags = item.tags || []
                    return (this.blog.tags || []).some((tag) => tags.indexOf(tag) >= 0)
                }).slice(0, 5)
            },
            goBlog(item) {
                if (item) this.$router.push('/mobile/user/blog/details/' + item.id)
            },
            editBlog() {
                // 编辑器只实现于桌面布局
                this.$router.push('/user/blog/edit/' + this.blog.id)
            },
            // 给真实标题节点设置目录 id，不在 Markdown 中注入 HTML。
            applyHeadingIds() {
                const headings = this.$el.querySelectorAll('.markdown-body h2, .markdown-body h3')
                this.toc.forEach((item, index) => {
                    if (headings[index]) headings[index].id = item.id
                })
            },
            scrollTo(id) {
                const el = document.getElementById(id)
                if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' })
            }
        }

    }
</script>


