<template>
    <div style="min-height: 600px" v-loading="loading">
        <el-alert v-if="loadError" title="文章载入失败，请返回列表后重试编辑。" type="error" :closable="false" style="margin-bottom:16px"></el-alert>
        <el-card v-if="!loadError" shadow="never" style="margin-bottom: 20px">
            <el-form ref="form" :model="form" label-width="80px" :rules="ruleValidate">
                <el-form-item label="标题" prop="title">
                    <el-input v-model="form.title" :disabled="true"></el-input>
                </el-form-item>
                <el-form-item label="简要说明" prop="description">
                    <el-input v-model="form.description" type="textarea" placeholder="一句话摘要,会显示在列表卡片与分享卡片上"></el-input>
                </el-form-item>
                <el-form-item label="分类">
                    <el-input v-model="form.category" maxlength="20" placeholder="如:国学 / 术数 / 随笔(同一分类会自动聚合到导航)"></el-input>
                </el-form-item>
                <el-form-item label="标签">
                    <el-select v-model="form.tags" multiple filterable allow-create default-first-option
                        placeholder="输入标签后回车,可添加多个" style="width:100%">
                    </el-select>
                </el-form-item>
                <el-form-item label="封面图">
                    <el-input v-model="form.cover" placeholder="封面图片 URL(选填,留空则不显示封面)"></el-input>
                </el-form-item>
                <el-form-item label="博客正文" prop="content">
                    <mavon-editor @imgAdd="imgAdd" style="max-height: 500px" ref="md" v-model="form.content" :subfield="false" :toolbars="mavonEditorToolbars"
                    />
                </el-form-item>
                <el-form-item>
                    <el-button type="primary" @click="onSubmit" :loading="submitButton.loading" :disabled="submitButton.disabled">修改</el-button>
                    <el-button @click="$router.push('/user/blog/main')">返回</el-button>
                </el-form-item>
            </el-form>
        </el-card>
        <token-dialog ref="tokenDialog"></token-dialog>
    </div>
</template>
<script>
    import { mapGetters } from 'vuex'
    import TokenDialog from '@/views/common/TokenDialog'
    import GistApi from '@/api/gist'
    export default {
        components: {
            TokenDialog
        },
        data() {
            return {
                form: {
                    id: "",
                    title: "",
                    originalTitle: "",
                    description: "",
                    content: "",
                    category: "",
                    tags: [],
                    cover: ""
                },
                ruleValidate: {
                    title: [
                        { required: true, message: '请输入标题', trigger: 'blur' },
                        { type: 'string', max: 32, message: '标题长度不大于32字符', trigger: 'change' }
                    ],
                    description: [
                        { required: true, message: '请输入博客描述', trigger: 'blur' }
                    ],
                    content: [
                        { required: true, message: '请输博客入正文', trigger: 'blur' }
                    ],
                },
                loading: true,
                loadError: false,
                submitButton: {
                    loading: false,
                    disabled: false
                },
                mavonEditorToolbars: {
                    bold: true,
                    italic: true,
                    header: true,
                    underline: true,
                    strikethrough: true,
                    mark: true,
                    superscript: true,
                    subscript: true,
                    quote: true,
                    ol: true,
                    ul: true,
                    link: true,
                    imagelink: true,
                    code: true,
                    table: true,
                    htmlcode: true,
                    trash: true,
                    alignleft: true,
                    aligncenter: true,
                    alignright: true,
                    preview: true,
                },
            }
        },
        computed: {
            ...mapGetters([
                'token',
            ])
        },
        mounted() {
            if (!this.token) {
                this.$nextTick(() => {
                    this.$message({
                        message: '权限不足',
                        type: 'error'
                    })
                    this.$router.replace('/user/blog/main')
                })
                return
            }
            this.loading = true
            this.form.id = this.$route.params.id
            GistApi.single(this.form.id).then(async (response) => {
                let result = response.data
                const key = Object.keys(result.files || {})[0]
                if (!key) throw new Error('Gist 中没有可编辑的文件')
                const file = result.files[key]
                const content = await GistApi.fileContent(file)
                this.form['title'] = key
                this.form['originalTitle'] = key
                this.form['content'] = content
                this.form['description'] = result['summary'] || ''
                this.form['category'] = result['category'] || ''
                this.form['tags'] = result['tags'] || []
                this.form['cover'] = result['cover'] || ''
            }).catch((error) => {
                this.loadError = true
                if (error && error.message) this.$message({ message: error.message, type: 'error' })
            }).then(() => {
                this.loading = false
            })
        },
        methods: {
            imgAdd(pos, file) {
                this.$refs.md.$img2Url(pos, file.miniurl)
            },
            onSubmit() {
                if (this.loadError || this.loading) return
                if (this.token) {
                    this.publish()
                } else {
                    this.$refs.tokenDialog.open(() => {
                        this.$message({ message: 'Token 已绑定，请再次点击修改', type: 'success' })
                    })
                }
            },
            publish() {
                this.$refs['form'].validate((valid) => {
                    if (!valid || this.submitButton.loading) return
                    this.submitButton.loading = true
                    this.submitButton.disabled = true
                    GistApi.edit(this.form).then((response) => {
                        const result = response.data
                        this.$message({ message: '修改成功', type: 'success' })
                        this.$router.push('/user/blog/details/' + result.id)
                    }).catch(() => {}).then(() => {
                        this.submitButton.loading = false
                        this.submitButton.disabled = false
                    })
                })
            }
        }
    }
</script>

<style>
</style>


