import axios from 'axios'
import Vue from 'vue'
import store from '../store/index'

const service = axios.create({
    baseURL: "https://api.github.com",
    timeout: 20000,
    headers: {
        // 2022-11-28 起 GitHub 推荐显式声明 API 版本
        'X-GitHub-Api-Version': '2022-11-28'
    }
})

service.interceptors.request.use(
    config => {
        let token = store.state.token.token
        const headers = config.headers || (config.headers = {})
        // Explicit credentials (e.g. candidate token validation) must win over stored credentials.
        if (token && !headers['Authorization'] && !headers['authorization']) {
            // 2021-09 起 ?access_token=xxx 已被移除, 必须走 Authorization 头
            headers['Authorization'] = 'Bearer ' + token
        }
        config.headers['Accept'] = 'application/vnd.github+json'
        return config
    },
    error => {
        return Promise.reject(error)
    }
)


service.interceptors.response.use(
    response => {
        return response
    },
    error => {
        let message = "请求失败"
        if (error.response) {
            switch (error.response.status) {
                case 401:
                    message = "Token 无效或已过期, 请重新绑定 (需 classic PAT 并勾选 gist / repo)"
                    break
                case 403: {
                    const headers = error.response.headers || {}
                    const remaining = headers['x-ratelimit-remaining']
                    const retryAfter = headers['retry-after']
                    if (retryAfter) {
                        message = `GitHub API 被临时限流, 约 ${retryAfter} 秒后恢复`
                    } else if (remaining === '0' || remaining === 0) {
                        let reset = parseInt(headers['x-ratelimit-reset'], 10)
                        let time = reset ? new Date(reset * 1000).toLocaleTimeString() : "稍后"
                        message = `GitHub API 限流 (未绑定 Token 时仅 60 次/小时), ${time} 后恢复`
                    } else {
                        message = "没有权限访问该资源 (若 Token 有效但报错, 检查是否勾选了 gist scope)"
                    }
                    break
                }
                case 404:
                    // 无 gist scope 时 GitHub 对受保护资源也可能返回 404
                    message = "资源不存在 (404); 若刚绑定 Token, 也请检查是否勾选了 gist scope"
                    break
                case 422:
                    message = "提交被拒绝 (422): " + (error.response.data.message || "参数不合法")
                    break
                default:
                    message = error.response.data.message || ("请求失败 (" + error.response.status + ")")
                    break
            }
        } else if (error.message && error.message.indexOf('timeout') >= 0) {
            message = "请求超时, 检查网络或代理"
        }
        Vue.prototype.$message({
            message: message,
            type: 'error',
            duration: 5000
        })
        return Promise.reject(error)
    }
)

export default service



